      arch?: string | null;
      /** Format: date-time */
      created_at: string;
      filename: string;
      /** Format: uuid */
      id: string;
      kind: components["schemas"]["ArtifactKind"];
      /** @description External delivery location (GitHub Release asset URL), when present. */
      mirror_url?: string | null;
      object_key?: string | null;
      platform: components["schemas"]["Platform"];
      /** Format: uuid */
      release_id: string;
      sha256: string;
